INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p302913-acct304', 'stk-maximus-27', 'ACCT 304', 'info', '{"desc": "أخوي بصراحة شغل متعوب عليه\n\nولكن\n\nElectives = المواد الإختيارية - وهذه يختارها الطالب بناءً على رغبتة وميوله. (وهي ليست إجبارية).\n\nالمواد الاليكتيف مو مخير بأنو ياخذها او لا\nهذي يختار الكورس الي يبغاه\n\nمثلا في الاكاونتنق\nعندك كورسين اليكتيف\nاذا جاء وقت هذي المادة تختار الكورس مثلا acct304 أو ةلف440\nتختار احد هالكورسين\n\nارجوا ان لا اكون مخطأ\n\nومرة ثانية مشكور وما قصرت على هالمجهود", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/65620/8", "user": "MAXIMUS-27", "ts": 1219514739000, "tid": 65620, "pn": 8}}', 1219514739000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
